def truncate_message(self, message):
    msg_bytes = message.encode('utf-8')

    if len(json.dumps(message)) <= 8015:
        return message

    low, high = 0, 8000
    while low < high:
        middle = (low + high + 1) // 2
        if len(json.dumps(_bytes2utf8(msg_bytes[:middle]))) <= 8000:
            low = middle
        else:
            high = middle - 1
    msg_bytes = msg_bytes[:low]

    message = _bytes2utf8(msg_bytes)
    return message + "... [truncated]"

